     1→import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
     2→import { Outlet, useLoaderData, useNavigation, useRouteError } from "react-router";
     3→import { boundary } from "@shopify/shopify-app-react-router/server";
     4→import { AppProvider } from "@shopify/shopify-app-react-router/react";
     5→import {
     6→  AppProvider as PolarisAppProvider,
     7→  SkeletonPage,
     8→  Layout,
     9→  Card,
    10→  SkeletonBodyText,
    11→  SkeletonDisplayText,
    12→} from "@shopify/polaris";
    13→import "@shopify/polaris/build/esm/styles.css";
    14→import enTranslations from "@shopify/polaris/locales/en.json";
    15→
    16→import { authenticate } from "../shopify.server";
    17→
    18→export const loader = async ({ request }: LoaderFunctionArgs) => {
    19→  await authenticate.admin(request);
    20→
    21→  // eslint-disable-next-line no-undef
    22→  return { apiKey: process.env.SHOPIFY_API_KEY || "" };
    23→};
    24→
    25→// Skeleton shown during page-to-page navigation transitions inside the app shell.
    26→// useNavigation must be called inside PolarisAppProvider so Polaris context is available.
    27→function AppContent() {
    28→  const navigation = useNavigation();
    29→  const isNavigating = navigation.state === "loading";
    30→
    31→  if (isNavigating) {
    32→    return (
    33→      <SkeletonPage primaryAction>
    34→        <Layout>
    35→          <Layout.Section>
    36→            <Card>
    37→              <SkeletonDisplayText size="small" />
    38→              <SkeletonBodyText lines={3} />
    39→            </Card>
    40→          </Layout.Section>
    41→          <Layout.Section>
    42→            <Card>
    43→              <SkeletonBodyText lines={6} />
    44→            </Card>
    45→          </Layout.Section>
    46→          <Layout.Section>
    47→            <Card>
    48→              <SkeletonBodyText lines={4} />
    49→            </Card>
    50→          </Layout.Section>
    51→        </Layout>
    52→      </SkeletonPage>
    53→    );
    54→  }
    55→
    56→  return <Outlet />;
    57→}
    58→
    59→export default function App() {
    60→  const { apiKey } = useLoaderData<typeof loader>();
    61→
    62→  return (
    63→    <AppProvider embedded apiKey={apiKey}>
    64→      <PolarisAppProvider i18n={enTranslations}>
    65→        <s-app-nav>
    66→          <s-link href="/app">Dashboard</s-link>
    67→          <s-link href="/app/zip-codes">Zip Codes</s-link>
    68→          <s-link href="/app/delivery-rules">Delivery Rules</s-link>
    69→          <s-link href="/app/waitlist">Waitlist</s-link>
    70→          <s-link href="/app/widget">Widget Customization</s-link>
    71→          <s-link href="/app/help">Help &amp; Support</s-link>
    72→          <s-link href="/app/settings">Settings</s-link>
    73→        </s-app-nav>
    74→        <AppContent />
    75→      </PolarisAppProvider>
    76→    </AppProvider>
    77→  );
    78→}
    79→
    80→// Shopify needs React Router to catch some thrown responses, so that their headers are included in the response.
    81→export function ErrorBoundary() {
    82→  return boundary.error(useRouteError());
    83→}
    84→
    85→export const headers: HeadersFunction = (headersArgs) => {
    86→  return boundary.headers(headersArgs);
    87→};
